import { slug as githubSlug } from 'github-slugger';

/** Keep the nested public URLs generated by the original Astro 4 collections. */
export function legacyContentId({ entry, data }: { entry: string; data: Record<string, unknown> }): string {
  if (data.slug !== undefined) {
    if (typeof data.slug !== 'string') throw new TypeError('Content slug must be a string.');
    return data.slug;
  }
  return entry.replace(/\\/g, '/').replace(/\.[^.]+$/, '')
    .split('/').map(segment => githubSlug(segment)).join('/').replace(/\/index$/, '');
}
